import { describe, it, expect } from 'vitest';
import { parse } from 'node-html-parser';

// Sanitizer under test: SANITIZER=naive (red) | fixed (green)
const impl = process.env.SANITIZER ?? 'fixed';
const { sanitize } = await import(`../src/${impl}.js`);

// ---------- helpers ----------

// Minimal entity decoder so checks see what a browser would see.
export function decodeEntities(s) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", colon: ':', semi: ';', x3a: ':' };
  return s
    .replace(/&#[xX]([0-9a-fA-F]+);?/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);?/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&([a-zA-Z][a-zA-Z0-9]*);/g, (m, n) => named[n.toLowerCase()] ?? m);
}

// A scheme is executable if, once decoded and stripped of control chars,
// it is javascript:, vbscript:, data: (can execute html), etc.
function isExecutableUrl(value) {
  const cleaned = decodeEntities(value).toLowerCase().replace(/[\s\x00-\x1f]/g, '');
  return /^(javascript|vbscript|data|livescript|mocha):/.test(cleaned);
}

// Assert parsed HTML contains no executable vector:
//  - no on* attribute anywhere (checked after entity decoding)
//  - no <script>, <iframe>, <object>, <embed>, <svg>, <math> elements
//  - no javascript:/vbscript:/data: URL in any URL-bearing attribute
function assertNoVector(html) {
  const root = parse(html);
  for (const el of root.querySelectorAll('*')) {
    const tag = el.rawTagName?.toLowerCase();
    expect(tag, `element <${tag}> survived in: ${html}`).not.toMatch(
      /^(script|iframe|object|embed|svg|math)$/
    );
    // node-html-parser exposes decoded attrs via .attributes; decode again anyway
    for (const [name, value] of Object.entries(el.attributes ?? {})) {
      expect(/^on/i.test(decodeEntities(name)), `attribute ${name}= on <${tag}> in: ${html}`).toBe(false);
      if (/^(href|src|xlink:href|action|formaction|srcdoc)$/i.test(name)) {
        if (name.toLowerCase() === 'srcdoc') {
          // srcdoc is an entire HTML document; any script/on-event inside is executable
          expect(value + decodeEntities(value), `executable srcdoc on <${tag}> in: ${html}`).not.toMatch(/script|on\w+\s*=/i);
        } else {
          expect(isExecutableUrl(value), `${name}="${value}" is an executable URL in: ${html}`).toBe(false);
        }
      }
    }
  }
}

// ---------- payloads (each exploits a distinct flaw) ----------

const PAYLOADS = [
  ['single-quoted event handler (naive only strips double quotes)',
    `<img src=x onerror='alert(1)'>`],

  ['unquoted event handler',
    `<img src=x onerror=alert(1)>`],

  ['nested marker reassembling after one removal pass',
    `<a href="jajavascript:vascript:alert(1)">click</a>`],

  ['case-split with entity-encoded tab inside scheme',
    `<a href="jav&#x09;ascript&#58;alert(1)">click</a>`],

  ['fully entity-encoded scheme',
    `<a href="&#106;&#97;&#118;&#97;&#115;&#99;&#114;&#105;&#112;&#116;&#58;alert(1)">click</a>`],

  ['iframe vector untouched by all three regexes',
    `<iframe src="javascript:alert(1)" onload="alert(2)"></iframe>`],

  ['script content survives tag stripping via split closing tag',
    `<scr<script></script>ipt>alert(1)</script>`],
];

describe(`sanitizer (${impl})`, () => {
  for (const [name, payload] of PAYLOADS) {
    it(`neutralizes: ${name}`, () => {
      assertNoVector(sanitize(payload));
    });
  }

  it('preserves benign markup', () => {
    const out = sanitize('<p>Hello <b>world</b> <a href="https://example.com">link</a></p>');
    expect(out).toContain('Hello');
    expect(out).toContain('<b>world</b>');
    expect(out).toContain('https://example.com');
  });
});

