import { parse } from 'node-html-parser';

// Parse-and-rebuild allowlist sanitizer.
// Strategy: never try to "clean" hostile markup in place (removal regexes are
// bypassable via quoting, nesting, case, entities). Instead parse into a DOM,
// keep only allowlisted tags/attributes/URL schemes, and rebuild the output
// from scratch with aggressive escaping. Anything unknown is dropped.

const ALLOWED_TAGS = new Set([
  'a', 'p', 'br', 'hr', 'span', 'div', 'b', 'i', 'em', 'strong', 'u', 's',
  'ul', 'ol', 'li', 'blockquote', 'pre', 'code', 'h1', 'h2', 'h3', 'h4',
  'h5', 'h6', 'img', 'table', 'thead', 'tbody', 'tr', 'td', 'th',
]);

// Elements whose *content* must be dropped entirely when the element is
// dropped (scripts/styles could reassemble or confuse parsers if unwrapped).
const DROP_WITH_CONTENT = new Set(['script', 'style', 'iframe', 'object', 'embed', 'noscript']);

const VOID_TAGS = new Set(['br', 'hr', 'img']);

const ALLOWED_ATTRS = new Set(['title']);
const URL_ATTRS = new Set(['href', 'src']); // validated against safe schemes

function decodeEntities(s) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", colon: ':' };
  return s
    .replace(/&#[xX]([0-9a-fA-F]+);?/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);?/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&([a-zA-Z][a-zA-Z0-9]*);/g, (m, n) => named[n.toLowerCase()] ?? m);
}

function escapeText(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function escapeAttr(s) {
  return s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Validate a URL after entity-decoding and stripping control characters,
// so "jav\tascript:", "&#106;avascript:" etc. cannot smuggle through.
export function isSafeUrl(value) {
  const cleaned = decodeEntities(value).toLowerCase().replace(/[\s\x00-\x1f]/g, '');
  // relative URLs and fragment/mailto are fine; block anything with an
  // executable scheme or scheme-looking prefix we don't recognize
  if (/^(javascript|vbscript|data|livescript|mocha|file):/.test(cleaned)) return false;
  if (/^[a-z][a-z0-9+.-]*:/.test(cleaned)) {
    // some other absolute scheme: only http(s) allowed
    return /^https?:/.test(cleaned);
  }
  return true; // relative path, anchor, protocol-relative
}

function cleanNode(node, out) {
  for (const child of node.childNodes ?? []) {
    if (child.nodeType === 3) {           // text
      out.push(escapeText(child.text));
      continue;
    }
    if (child.nodeType !== 1) continue;   // skip comments, doctype, etc.

    const tag = child.rawTagName?.toLowerCase();
    if (!tag || !ALLOWED_TAGS.has(tag)) {
      if (!DROP_WITH_CONTENT.has(tag)) cleanNode(child, out); // unwrap unknown tags
      continue;                              // drop dangerous ones entirely
    }

    const attrs = [];
    for (let [name, value] of Object.entries(child.attributes ?? {})) {
      name = name.toLowerCase();
      value = value ?? '';
      if (/^on/i.test(name)) continue;                    // no event handlers ever
      if (!ALLOWED_ATTRS.has(name) && !URL_ATTRS.has(name)) continue;
      if (URL_ATTRS.has(name) && !isSafeUrl(value)) continue;
      attrs.push([name, value]);
    }
    // href/src only make sense on their elements; a bare src on <p> is junk
    const filtered = attrs.filter(([n]) =>
      !(n === 'href' && tag !== 'a') && !(n === 'src' && tag !== 'img'));

    const attrStr = filtered.map(([n, v]) => ` ${n}="${escapeAttr(v)}"`).join('');
    out.push(`<${tag}${attrStr}>`);
    if (!VOID_TAGS.has(tag)) {
      cleanNode(child, out);
      out.push(`</${tag}>`);
    }
  }
}

export function sanitize(html) {
  const root = parse(String(html ?? ''), { comment: false });
  const out = [];
  cleanNode(root, out);
  return out.join('');
}

